import{_ as a,o,c as e,a2 as s}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"一次 63 分钟的任务卡死：被拒绝的审批事实如何堵住取消流程","description":"用户点了停止却一直停在取消中。根因不是 UI，而是一条被云端拒绝的审批事实堵住了取消屏障，出站队列每 30 秒重试一次，永远不会自己好。","frontmatter":{"title":"一次 63 分钟的任务卡死：被拒绝的审批事实如何堵住取消流程","date":"2026-11-04T00:00:00.000Z","tags":["分布式状态机","最终一致性","HITL","出站队列"],"description":"用户点了停止却一直停在取消中。根因不是 UI，而是一条被云端拒绝的审批事实堵住了取消屏障，出站队列每 30 秒重试一次，永远不会自己好。"},"headers":[],"relativePath":"posts/approval-deadlock.md","filePath":"posts/approval-deadlock.md"}'),n={name:"posts/approval-deadlock.md"};function d(p,t,u,l,r,q){return o(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="一次-63-分钟的任务卡死-被拒绝的审批事实如何堵住取消流程" tabindex="-1">一次 63 分钟的任务卡死：被拒绝的审批事实如何堵住取消流程 <a class="header-anchor" href="#一次-63-分钟的任务卡死-被拒绝的审批事实如何堵住取消流程" aria-label="Permalink to &quot;一次 63 分钟的任务卡死：被拒绝的审批事实如何堵住取消流程&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>某金融终端 Agent 平台的写操作审批链路：执行端把&quot;待用户确认的写操作&quot;冻结成提案，云端生成确认卡，用户批准后才落库。审批、取消与执行结果都以&quot;事实&quot;先写入执行端出站队列，再由后台投递到云端，保证同一任务内事实有序、可追溯。问题出在链路合同上。</p><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>用户发起&quot;把一只股票加入指定自选分组&quot;，模型回复&quot;我准备……需要你确认&quot;，确认卡从未出现；界面显示&quot;取消中 63 分钟&quot;，多次点击停止无效，任务停在取消中。写操作没有发生，没有脏数据，但任务结束不了，占住会话与执行槽位，只能重启。取消完成事实每 30 秒重试一次，重启前累计 50+ 次，始终没投递成功。</p><h2 id="排查-从假设到证据" tabindex="-1">排查：从假设到证据 <a class="header-anchor" href="#排查-从假设到证据" aria-label="Permalink to &quot;排查：从假设到证据&quot;">​</a></h2><p><strong>先怀疑 UI。</strong> 现象最像界面卡住：卡片不出来，按钮没反应。查确认卡的数据来源与前端日志，再查云端有没有生成过审批请求记录：云端审批请求表里没有该任务的任何行，前端根本没有数据可渲染。同时每次点&quot;停止&quot;都成功提交了取消命令，取消记录只有一条，后续点击是重复提交。按钮没坏，问题在上游。</p><p><strong>再怀疑模型或网络。</strong> 按时间线比对执行端出站事实与云端回执：14:00:48.656 发出审批事实，14:00:48.766 云端拒收——身份冲突，提示&quot;审批必须与云端已核验的提案一致&quot;，相隔 110 毫秒。业务侧冻结提案已存在，字段完整。请求发出去了，是被强校验拒收；提案没问题，缺的是审批事实里回显的提案快照。</p><p><strong>转向取消：命令没送到？</strong> 取消命令已被接受；14:02:42 取消清理完成，生成&quot;取消完成&quot;事实（队列第 20 条），状态是待投递；前一条审批事实（第 19 条）是已拒绝。取消状态记录结果为空，后续动作仍待处理。取消执行完了，卡在这条事实的投递上。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>14:00:48.656  执行端 ──审批事实（缺提案快照）──&gt; 云端</span></span>
<span class="line"><span>14:00:48.766  执行端 &lt;──拒收：身份冲突────────── 云端     → 确认卡从未生成</span></span>
<span class="line"><span>14:02:42      取消清理完成，生成&quot;取消完成&quot;事实（队列第 20 条）</span></span>
<span class="line"><span>              屏障：前序事实必须终结</span></span>
<span class="line"><span>                第 19 条 审批事实 = 已拒绝（不会再投递）</span></span>
<span class="line"><span>                第 20 条 取消完成 = 待投递（每 30 秒重试，累计 50+ 次）</span></span>
<span class="line"><span>              → 取消证明没有出口，任务停在取消中 63 分钟</span></span></code></pre></div><p><strong>最后怀疑队列或数据库故障。</strong> 队列每 30 秒稳定重试，报错是&quot;事实投递未完成&quot;，不是连接失败或死锁。日志显示它卡在&quot;前序事实必须终结&quot;，挡路的正是那条被拒的审批事实；取消例外白名单只覆盖另外两类场景，不含&quot;被拒的审批暂停事实&quot;。不是基础设施故障，是规则不完备。</p><p><strong>排除改库。</strong> 提案字段与云端校验口径一致；旧任务不改数据，只重启带修复的构建就全状态收敛。数据没坏，是代码路径问题。</p><p>排查顺序按否证成本定：先排最像的 UI，再排网络；确认审批侧断点后才转向取消；直到看见&quot;取消完成已生成但待投递、前一条已拒绝&quot;，才怀疑屏障规则。</p><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><p>两层缺陷叠加，缺一不可。</p><p>直接触发是事实合同不一致：执行端把内部审批载荷转成对外事实时，按&quot;动作类型白名单&quot;决定是否透传提案快照；本次写操作不在白名单，字段被静默丢弃。云端同期新增的强校验要求快照与冻结提案逐字段一致，于是以&quot;身份冲突&quot;拒收。审批事实从未落库，确认卡从未生成。</p><p>放大成永久卡死的是取消屏障例外不完备：出站队列用&quot;前序事实必须终结&quot;做屏障，保证同一任务内事实全序。取消完成事实的前一条正是那条被拒事实；它不会再投递，屏障永远不会解除。白名单只放行另外两类场景，没算上&quot;被云端耐久拒绝的审批暂停事实&quot;。于是取消证明每 30 秒重试、永远待投递，任务状态机停在取消中，再点停止只是重复提交同一条已接受的命令。</p><p>一句话：一个字段在事实转换时被丢了，一条被拒事实又把取消的唯一出口堵死。和模型、网络、数据库、用户操作步骤都无关。</p><h2 id="修复方案与取舍" tabindex="-1">修复方案与取舍 <a class="header-anchor" href="#修复方案与取舍" aria-label="Permalink to &quot;修复方案与取舍&quot;">​</a></h2><p>方案 A（放弃）：放宽云端校验，缺快照就跳过一致性检查，或由云端反查补全。这会削弱&quot;防审批对象被替换&quot;的校验，用安全换可用；用户看到的内容与实际写入不一致，授权就失去意义。</p><p>方案 B（采用）：补齐事实合同，同时收窄取消屏障例外。执行端对写操作同样透传提案快照；把&quot;被云端拒绝的审批暂停事实&quot;加入例外，并收紧条件：只有取消发起方、同一次执行尝试、同一执行相位下的取消证明可越过。改动集中在产生事实的一侧，不降低验证强度。</p><p>方案 C（拒绝）：改库把取消事实标成已接受、改任务状态，或重发、伪造回执。破坏可追溯性，掩盖缺陷，下次还会复现。</p><p>为什么必须同时改两处——只改一处，故障会在另一条路径上复发：</p><ul><li>只改例外：任务能取消，但审批事实照样被拒，确认卡永远不出现，用户还是批不了。等于把&quot;卡死&quot;换成&quot;永远无法批准&quot;。</li><li>只改载荷：新任务能正常审批，但被拒事实按可追溯性原样保留，屏障仍被堵住；下一次拒收还会堵死取消。只修了触发条件。</li><li>两处都改：新合同一致，旧任务重启后靠例外越过被拒事实收敛。一处管&quot;不再产生坏事实&quot;，一处管&quot;坏事实不堵死出口&quot;。</li></ul><p>没有选&quot;取消走独立队列&quot;：会引入跨队列因果，消费端要处理乱序，复杂度高于维护显式例外清单；代价是清单要长期维护，每新增一类都要配测试。配套同步了架构文档，补 3 项单测和 1 项真实数据库集成用例。</p><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>修复前</th><th>修复后</th><th>口径 / 环境</th></tr></thead><tbody><tr><td>卡住任务收敛</td><td>取消中 63 分钟；取消完成事实待投递，后续动作待处理，结果为空</td><td>结果已取消、取消事实已接受、后续动作完成、执行记录关闭</td><td>单机（云端 API、执行端、桌面端均为宿主进程）、真实数据库；15:18:13 重启后直接查库，零修补</td></tr><tr><td>取消事实投递</td><td>每 30 秒一次，重启前 50+ 次，始终待投递</td><td>重启后一次投递即被接受</td><td>出站队列表 + 服务日志</td></tr><tr><td>相关单测</td><td>—</td><td>52/52 通过（新增 3 项）</td><td>类型检查通过；覆盖快照保留、原行为不变、无关动作不扩权</td></tr><tr><td>真实数据库集成</td><td>185/185 通过</td><td>186/186 通过（新增 1 项，原 185 项无回归）</td><td>真实 PostgreSQL；新增用例锁定&quot;被拒审批暂停不阻塞同一次执行尝试的取消完成&quot;</td></tr><tr><td>构建产物</td><td>—</td><td>两处修复都进入运行包</td><td>构建时间 15:17:41，产物检索确认</td></tr></tbody></table><p>这个表格不代表端到端验收。环境是单机、本地、单任务，多实例并发下的屏障与重试没有验证；真实模型手测也没做：确认卡是否出现、先拒绝再批准、真实页面核对写入，都还没做。同类&quot;提问暂停&quot;事实放进了例外，但没有专属回归用例。新增集成用例没保留修复前的失败记录，检出能力是推断。改动只在工作树，未提交、未推送，被拒事实原样保留。</p><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><ol><li>先按&quot;最像什么&quot;排查，但每个假设都要有一个能否证的证据。UI 假设是被&quot;云端审批请求表没有任何行&quot;否掉的，不是靠&quot;看起来不像 UI 问题&quot;排除的。</li><li>卡住的位置不等于出错的位置。错误在 14:00:48 的载荷转换，卡死在 14:02:42 之后的屏障；只盯任务状态，会一直在取消逻辑里打转。</li><li>修触发条件，也要修放大机制。字段丢失是一次性的，屏障缺例外把它变成永久故障；重试和幂等只保证&quot;不丢&quot;，不保证&quot;能过&quot;。也不要用改库或放宽校验换收敛。</li></ol><p>没做到的部分：多实例并发没验证，真实模型手测和同类场景回归还没补，&quot;提问暂停&quot;的例外没有专属用例，新增用例的失败检出能力也只是推断。这些我都留在记录里，没有写成&quot;已验收&quot;。</p>`,31)])])}const c=a(n,[["render",d]]);export{h as __pageData,c as default};
